using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Collections.Generic;
namespace PZ3D {static class VersionPreserveProgress {
 static int checks;static void Check(bool value,string text){checks++;if(!value)throw new Exception("FAIL "+text);}static string Stage(VersionCopyProgress p){var field=typeof(VersionCopyProgress).GetField("Stage");return field==null?"":(string)field.GetValue(p);}static void Put(string p,string t){Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,t,new UTF8Encoding(false));}
 public static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);string game=Path.Combine(root,"原游戏"),data=Path.Combine(root,"数据"),user=Path.Combine(root,"用户");Put(Path.Combine(game,"ProjectZomboid64.exe"),"isolated; never execute");Put(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(game,"version.txt"),"42.21.0");Put(Path.Combine(game,"media","中文.bin"),new string('x',3*1024*1024));Directory.CreateDirectory(user);var library=new VersionLibrary(data,game,user);var events=new List<VersionCopyProgress>();string target=Path.Combine(root,"成功副本");var row=library.Preserve(game,target,"测试副本",CancellationToken.None,p=>events.Add(p));
 Check(events.Count>0&&Stage(events[0])=="scan","native scan emits progress before transfer begins");Check(events.Any(p=>Stage(p)=="verifySource"),"final source hashing is visible");Check(events.Any(p=>Stage(p)=="verifyCopy"),"copied file verification is visible");Check(File.ReadAllBytes(Path.Combine(target,"media","中文.bin")).SequenceEqual(File.ReadAllBytes(Path.Combine(game,"media","中文.bin"))),"actual independent bytes match");Put(Path.Combine(game,"media","中文.bin"),"source changed after copy");Check(new FileInfo(Path.Combine(target,"media","中文.bin")).Length==3*1024*1024,"copy remains independent after source edit");
 foreach(string stage in new[]{"scan","copy","verifyCopy","verifySource"}){string destination=Path.Combine(root,"取消-"+stage);int before=library.List().Count;using(var token=new CancellationTokenSource()){bool cancelled=false;try{library.Preserve(game,destination,"cancel",token.Token,p=>{if(Stage(p)==stage&&p.BytesCopied>0)token.Cancel();});}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"cancellable after actual bytes processed "+stage);Check(!Directory.Exists(destination)&&!Directory.GetDirectories(root,"取消-"+stage+".partial-*").Any(),"cancel cleanup "+stage);Check(library.List().Count==before,"cancel never registers "+stage);}}
 string failed=Path.Combine(root,"失败副本");bool altered=false,rejected=false;try{library.Preserve(game,failed,"failure",CancellationToken.None,p=>{if(Stage(p)=="copy"&&!altered){altered=true;Put(Path.Combine(game,"Steam-update.bin"),"changed during copy");}});}catch(IOException){rejected=true;}Check(rejected&&!Directory.Exists(failed),"changed source rejects and cleans real copy");Check(library.List().Count==2,"only successful copy is registered");Console.WriteLine("PASS VersionPreserveProgress "+checks+" checks; isolated actual files; no game entry. Fixture: "+root);return 0;}catch(Exception error){Console.WriteLine(error);return 1;}}
}}
